import json
from fractions import Fraction
from itertools import product

# Balance NaHSO3 + HCl -> NaCl + SO2 + H2O by exhaustive search over small coefficients.
ELEMENTS = ["Na", "H", "S", "O", "Cl"]
REACTANTS = {"NaHSO3": {"Na": 1, "H": 1, "S": 1, "O": 3}, "HCl": {"H": 1, "Cl": 1}}
PRODUCTS = {"NaCl": {"Na": 1, "Cl": 1}, "SO2": {"S": 1, "O": 2}, "H2O": {"H": 2, "O": 1}}

r_names = list(REACTANTS)
p_names = list(PRODUCTS)
all_species = [REACTANTS[n] for n in r_names] + [PRODUCTS[n] for n in p_names]
n_r = len(r_names)

def find_balance():
    for coeffs in product(range(1, 5), repeat=len(all_species)):
        ok = True
        for e in ELEMENTS:
            lhs = sum(coeffs[i] * all_species[i].get(e, 0) for i in range(n_r))
            rhs = sum(coeffs[i] * all_species[i].get(e, 0) for i in range(n_r, len(all_species)))
            if lhs != rhs:
                ok = False
                break
        if ok:
            return dict(zip(r_names + p_names, coeffs))
    return None

coef = find_balance()

if coef is None:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"reason": "no balanced equation found"}}
else:
    a_nahso3 = coef["NaHSO3"]
    a_hcl = coef["HCl"]
    b_h2o = coef["H2O"]

    # Water formed fixes the extent of reaction: water = extent * b_h2o.
    water_formed = Fraction(1)
    extent = water_formed / b_h2o

    # NaHSO3 supply (1 mole) must cover the extent.
    nahso3_supplied = Fraction(1)
    max_extent = nahso3_supplied / a_nahso3

    if extent > max_extent:
        result = {"final_answer": "UNSUPPORTED", "evidence": {"reason": "NaHSO3 limits water below 1 mole"}}
    else:
        hcl_moles = extent * a_hcl
        result = {
            "final_answer": str(hcl_moles),
            "evidence": {
                "balanced_coefficients": coef,
                "extent_of_reaction": str(extent),
                "max_extent_from_NaHSO3": str(max_extent),
                "HCl_moles": str(hcl_moles),
            },
        }

print(json.dumps(result))
